def sha(data):return hashlib.sha256(data).hexdigest()
def abort(msg):raise SystemExit('ABORTADO: '+msg)
def main():
 p=argparse.ArgumentParser(description=__doc__)
 p.add_argument('--root',default='/home/farcry/Documents/bch-flow')
 m=p.add_mutually_exclusive_group(required=True);m.add_argument('--dry-run',action='store_true');m.add_argument('--apply',action='store_true')
 args=p.parse_args();root=Path(args.root).expanduser().resolve()
 if not (root/'manage.py').is_file() or not (root/'app_bch_flow/templates/app_bch_flow/base.html').is_file():abort('raiz Django/base.html nao encontrados')
 for rel in ('static/app_bch_flow/videos/bch-flow-demo.mp4','static/app_bch_flow/images/bch-flow-demo.jpg'):
  if not (root/'app_bch_flow'/rel).is_file():abort('asset de video ausente: '+rel)
 files={}
 for rel,packed in PAYLOAD.items():
  try:data=zlib.decompress(base64.b85decode(packed))
  except Exception as e:abort('payload invalido: '+rel+' '+str(e))
  if sha(data)!=HASHES[rel]:abort('checksum invalido: '+rel)
  files[rel]=data
 html=files['templates/app_bch_flow/landing/index.html'].decode('utf-8')
 for needle in ('{% load static i18n %}','{% trans ','hackathon_presentation_url','hackathon_token_address','jury_configured',"{% url 'bch_flow:home' %}","{% url 'bch_flow:login' %}","{% url 'bch_flow:register' %}",'bch-flow-demo.mp4','bch-flow-demo.jpg'):
  if needle not in html:abort('contrato ausente: '+needle)
 if html.count('bch_flow:jury_enter')!=2 or html.count('{% csrf_token %}')!=2:abort('contrato CSRF/jurados nao preservado')
 for needle in ('landing-enterprise-v2.css','landing-enterprise-v2.js','landing-experience.js'):
  if needle in html:abort('dependencia visual legada: '+needle)
 try:
  from django.template import Engine
  Engine(debug=False).from_string(html)
  print('Django template: sintaxe OK')
 except ImportError:print('Django nao instalado neste Python; execute manage.py check no ambiente virtual')
 except Exception as e:abort('Django template invalido: '+str(e))
 changes=[]
 for rel,data in files.items():
  target=root/'app_bch_flow'/rel
  if target.is_symlink() or (not target.parent.is_dir() and (target.parent.exists() or rel!='static/app_bch_flow/images/brand/landing-logo.png')):abort('destino invalido: '+str(target))
  if target.exists():
   existing=sha(target.read_bytes())
   if existing==HASHES[rel]:continue
   if existing not in ALLOWED[rel]:abort('arquivo alterado fora das versoes auditadas: '+str(target))
  elif rel!='static/app_bch_flow/images/brand/landing-logo.png' and rel in ALLOWED and ALLOWED[rel]:abort('arquivo esperado ausente: '+str(target))
  changes.append((rel,target,data))
 print('BCH FLOW V4 — arquivos a instalar:',len(changes))
 for rel,_,data in changes:print(' ',rel,sha(data))
 print('Backend, shared base, providers e banco: intocados')
 if args.dry_run:print('DRY-RUN OK; nenhum arquivo modificado');return
 if not changes:print('V4 ja instalada; nenhuma alteracao');return
 backup=root/'.bch_flow_landing_backups'/('v4_'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ'))
 staged=[];done=[];orig={}
 try:
  backup.mkdir(parents=True,exist_ok=False)
  for rel,target,data in changes:
   if not target.parent.exists():target.parent.mkdir(parents=True,exist_ok=True)
   orig[rel]=sha(target.read_bytes()) if target.exists() else None
   if target.exists():
    copy=backup/rel;copy.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(target,copy)
    if sha(copy.read_bytes())!=orig[rel]:raise RuntimeError('backup invalido: '+rel)
   fd,tmp=tempfile.mkstemp(prefix='.bf_v4_',dir=target.parent)
   with os.fdopen(fd,'wb') as f:f.write(data);f.flush();os.fsync(f.fileno())
   staged.append((rel,target,tmp))
  for rel,target,tmp in staged:
   current=sha(target.read_bytes()) if target.exists() else None
   if current!=orig[rel]:raise RuntimeError('mudanca simultanea: '+rel)
   os.replace(tmp,target);done.append((rel,target))
   if sha(target.read_bytes())!=HASHES[rel]:raise RuntimeError('checksum apos escrita invalido: '+rel)
 except Exception as e:
  for rel,target in reversed(done):
   copy=backup/rel
   if copy.exists():shutil.copy2(copy,target)
   elif target.exists():target.unlink()
  abort(str(e)+' | rollback executado')
 finally:
  for _,_,tmp in staged:
   if os.path.exists(tmp):os.unlink(tmp)
 print('INSTALADO OK | Backup:',backup)
 print('Execute: cd '+str(root)+' && python3 manage.py check')
 print('Verifique a landing no navegador desktop/mobile; fidelidade visual depende de teste renderizado.')
if __name__=='__main__':main()
